func New(ds model.DataStore, artwork artwork.Artwork, streamer core.MediaStreamer, archiver core.Archiver,
	players core.Players, externalMetadata core.ExternalMetadata, scanner scanner.Scanner, broker events.Broker,
	playlists core.Playlists, scrobbler scrobbler.PlayTracker, share core.Share, playback playback.PlaybackServer,
) *Router {
	r := &Router{
		ds:               ds,
		artwork:          artwork,
		streamer:         streamer,
		archiver:         archiver,
		players:          players,
		externalMetadata: externalMetadata,
		playlists:        playlists,
		scanner:          scanner,
		broker:           broker,
		scrobbler:        scrobbler,
		share:            share,
		playback:         playback,
	}
	r.Handler = r.routes()
	return r
}

func (api *Router) routes() http.Handler {
	r := chi.NewRouter()

	r.Use(postFormToQueryParams)
	h(r, "getOpenSubsonicExtensions", api.GetOpenSubsonicExtensions)

	r.Group(func(r chi.Router) {
		r.Use(checkRequiredParameters)
		r.Use(authenticate(api.ds))
		r.Use(server.UpdateLastAccessMiddleware(api.ds))
		api.protectedRoutes(r)
	})
	return r
}

